import {initialJobs,portals} from './jobs.js';
import {analyze,extractKeywords,createDraft,escapeHtml as e,createDocx,createZip} from './engine.js';
const $=s=>document.querySelector(s);
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',file:'M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9Z M14 2v7h7 M7 13h10 M7 17h7',briefcase:'M4 7h16a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2Z M8 7V4h8v3 M2 12c6 4 14 4 20 0 M10 13h4',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M3 12h18 M12 3c5 5 5 13 0 18 M12 3c-5 5-5 13 0 18',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M12 7v5l3 2',arrow:'M5 12h14 M14 7l5 5-5 5',external:'M14 3h7v7 M21 3 10 14 M10 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-6',check:'m5 12 4 4L19 6',plus:'M12 5v14 M5 12h14',bookmark:'M6 3h12v18l-6-4-6 4Z',upload:'M12 16V3 M7 8l5-5 5 5 M3 15v5a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-5',download:'M12 3v13 M7 11l5 5 5-5 M3 15v5a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',leaf:'M20 3C9 2 2 7 5 15s15 6 15-12Z M5 20 16 9',close:'m6 6 12 12 M6 18 18 6',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4',menu:'M4 6h16 M4 12h16 M4 18h16',money:'M3 5h18v14H3Z M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',settings:'M4 7h16 M4 17h16 M9 4v6 M15 14v6',mail:'M3 5h18v14H3Z M3 5l9 8 9-8',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const KEY='civicpath-v1';
function load(){try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}}
const saved=load();
let state={view:'board',jobs:initialJobs.map(j=>({...j,bookmarked:false})),profile:{name:'',email:'',city:'',roles:'Customer service, records clerk'},resume:'',remember:false,applications:{},...validSaved(saved)};
let filter={q:'',sector:'All employers',city:'All locations',tab:'all',sort:'recommended'},selected=new Set(),detailId=null,detailTab='overview',toastTimer;
function validSaved(s){if(!s||s.version!==1)return{};return {jobs:Array.isArray(s.jobs)?s.jobs.slice(0,300).map(sanitizeJob):initialJobs,profile:{name:String(s.profile?.name||'').slice(0,150),email:String(s.profile?.email||'').slice(0,250),city:String(s.profile?.city||'').slice(0,100),roles:String(s.profile?.roles||'Customer service, records clerk').slice(0,300)},resume:s.remember?String(s.resume||'').slice(0,100000):'',remember:!!s.remember,applications:sanitizeApps(s.applications)}}
function sanitizeApps(apps){let out={};if(!apps||typeof apps!=='object')return out;for(const [key,a] of Object.entries(apps).slice(0,300)){if(!a||typeof a!=='object')continue;out[key]={text:String(a.text||'').slice(0,100000),cover:String(a.cover||'').slice(0,30000),status:['Draft','Ready','Submitted','Interview','Closed'].includes(a.status)?a.status:'Draft',reviewed:!!a.reviewed,confirmed:!!a.confirmed,notes:String(a.notes||'').slice(0,10000),confirmation:String(a.confirmation||'').slice(0,500),updated:String(a.updated||''),submitted:String(a.submitted||''),changes:Array.isArray(a.changes)?a.changes.map(String).slice(0,10):[]}}return out}
function safeUrl(u){try{const url=new URL(u);return url.protocol==='https:'&&!url.username&&!url.password?url.href:''}catch{return''}}
function sanitizeJob(j){let out={};for(const k of ['id','title','employer','city','location','salary','type','deadline','deadlineLabel','description','verified','notes'])out[k]=String(j?.[k]||'').slice(0,k==='description'?15000:500);out.id=out.id||`JOB-${crypto.randomUUID()}`;out.sector=j?.sector==='Provincial'?'Provincial':'Municipal';out.sourceUrl=safeUrl(j?.sourceUrl);out.applyUrl=safeUrl(j?.applyUrl)||out.sourceUrl;out.keywords=Array.isArray(j?.keywords)?j.keywords.map(String).filter(Boolean).slice(0,40):[];out.bookmarked=!!j?.bookmarked;out.status='Saved';return out}
function persist(){try{const apps=structuredClone(state.applications);if(!state.remember)for(const a of Object.values(apps)){a.text='';a.cover=''}localStorage.setItem(KEY,JSON.stringify({version:1,jobs:state.jobs,profile:state.profile,resume:state.remember?state.resume:'',remember:state.remember,applications:apps}))}catch{toast('This browser could not save the workspace. Export a backup to keep your work.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4600)}
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function days(j){return j.deadline?Math.round((new Date(j.deadline+'T12:00:00Z')-new Date(today()+'T12:00:00Z'))/86400000):null}
function deadline(j){const d=days(j);return d===null?'Check closing date':d<0?'Closing date passed':d===0?'Closes today':d===1?'Closes tomorrow':`Closes ${new Date(j.deadline+'T12:00:00Z').toLocaleDateString('en-CA',{month:'short',day:'numeric',timeZone:'America/Toronto'})}`}
const jobById=id=>state.jobs.find(j=>j.id===id);
function btn(action,label,ico='arrow',cls='outline',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${icon(ico)}${label}</button>`}
function official(url,label,cls='outline'){return safeUrl(url)?`<a class="btn ${cls}" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${label}${icon('external')}</a>`:''}
function stats(){const active=state.jobs.filter(j=>days(j)===null||days(j)>=0).length;const due=state.jobs.filter(j=>days(j)!==null&&days(j)>=0&&days(j)<=7).length;const apps=Object.values(state.applications);return `<div class="stats">${[['briefcase',active,'Open opportunities','in your workspace'],['clock',due,'Closing soon','next 7 days'],['file',apps.filter(a=>a.status==='Draft'||a.status==='Ready').length,'In preparation','your next steps'],['check',apps.filter(a=>['Submitted','Interview'].includes(a.status)).length,'Submitted','keep it growing']].map(([ico,num,label,sub])=>`<div class="stat"><div class="stat-icon">${icon(ico)}</div><div><div class="stat-label">${label}</div><div class="stat-num">${num}<span>${sub}</span></div></div></div>`).join('')}</div>`}
function render(){const labels={board:'Job board',resume:'Resume studio',applications:'Applications',portals:'Career portals'};$('#app').innerHTML=`<aside class="sidebar" id="sidebar"><a href="#board" class="logo" data-action="view" data-view="board"><span class="logo-symbol">${icon('home')}</span>CivicPath</a><div class="eyebrow">Your workspace</div><nav class="nav" aria-label="Main navigation">${[['board','grid','Job board'],['resume','file','Resume studio'],['applications','briefcase','Applications'],['portals','globe','Career portals']].map(([v,i,t])=>`<button data-action="view" data-view="${v}" class="${state.view===v?'active':''}" ${state.view===v?'aria-current="page"':''}>${icon(i)}${t}${v==='applications'?`<span class="count">${Object.keys(state.applications).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-card"><div class="sprig">${icon('leaf')}</div><h4>A little closer, every day.</h4><p>Good work begins with a place to grow. Let’s find yours in public service.</p><a href="https://www.gojobs.gov.on.ca/JobsAlert.aspx" target="_blank" rel="noopener noreferrer">Get OPS job alerts ${icon('external')}</a></div><div class="profile-mini"><div class="avatar">${e(state.profile.name?state.profile.name.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase():'Y')}</div><div><strong>${e(state.profile.name||'Your job journey')}</strong><small>Ontario, Canada</small></div><button class="icon-btn" data-action="view" data-view="resume" title="Edit profile" style="margin-left:auto;color:#b7c8ae;border:0">${icon('settings')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="mobile-brand"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span class="logo-symbol">${icon('home')}</span>CivicPath</div><div class="breadcrumb">Workspace <span>/</span> <strong>${labels[state.view]}</strong></div><div class="top-actions"><span class="date">${new Date().toLocaleDateString('en-CA',{timeZone:'America/Detroit',weekday:'short',month:'long',day:'numeric'})}</span><span class="private-label"><i class="private-dot"></i>Private workspace</span><button class="icon-btn" data-action="help" aria-label="Help and privacy">${icon('help')}</button></div></header><main class="main" id="main">${state.view==='board'?board():state.view==='resume'?studio():state.view==='applications'?applications():portalView()}</main></div>${state.view==='board'&&selected.size?`<div class="bulkbar"><span><strong>${selected.size}</strong> opportunit${selected.size===1?'y':'ies'} selected</span><button class="clear" data-action="clear-selection">Clear selection</button>${btn('prepare-selected','Prepare selected','spark','lime')}</div>`:''}`;}
function intro(kicker,title,text,action=''){return `<div class="page-intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${text}</p></div>${action}</div>`}
function board(){return `${intro('A new opportunity awaits','Your next chapter starts here.','Customer service & records roles. Toronto to Windsor.',btn('add-job','Add a job','plus'))}<div class="hero-row"><div class="setup-card"><div><div class="eyebrow">${state.resume?'Your experience. Your advantage.':'A good place to begin'}</div><h2>${state.resume?'Give every application<br>a personal touch.':'Great opportunities.<br>Meet your experience.'}</h2><p>${state.resume?'Your resume is ready. Select a role to find your strengths and prepare a tailored draft.':'Add your resume to see keyword coverage and prepare a draft for each opportunity.'}</p>${btn('view',state.resume?'Open resume studio':'Add your resume',state.resume?'file':'upload','primary','data-view="resume"')}</div><div class="paper-art" aria-hidden="true"><i></i><i></i><i style="width:70%"></i><i style="margin-top:17px"></i><i style="width:80%"></i><div class="art-badge">${icon('check')}</div></div></div><div class="tip-card"><div class="tip-icon">${icon('leaf')}</div><div><div class="eyebrow">A thoughtful approach</div><h3>Make every application count.</h3><p>Match the posting to experience you can prove. A clear example is stronger than a page of keywords.</p><a href="https://www.ontario.ca/page/careers-hiring-process" target="_blank" rel="noopener noreferrer">How Ontario hires ${icon('external')}</a></div></div></div>${stats()}<section aria-label="Job opportunities"><div class="section-heading"><div><h2>Opportunities for you <span class="muted small">↗</span></h2><p>Provincial & municipal roles, all in one place.</p></div>${btn('view','Explore career portals','globe','text','data-view="portals"')}</div><div class="tabs" role="group" aria-label="Opportunity groups">${[['all','All opportunities',state.jobs.length],['saved','Bookmarked',state.jobs.filter(j=>j.bookmarked).length],['closing','Closing soon',state.jobs.filter(j=>days(j)!==null&&days(j)>=0&&days(j)<=7).length]].map(([v,t,n])=>`<button class="${filter.tab===v?'active':''}" data-action="filter-tab" data-value="${v}">${t}<span class="tag-count">${n}</span></button>`).join('')}</div><div class="filters"><div class="search">${icon('search')}<input id="job-search" type="search" placeholder="Search title, employer or keyword…" aria-label="Search jobs" value="${e(filter.q)}"></div><select id="sector-filter" aria-label="Filter employer type">${['All employers','Provincial','Municipal'].map(v=>`<option ${filter.sector===v?'selected':''}>${v}</option>`).join('')}</select><select id="city-filter" aria-label="Filter location">${['All locations',...new Set([...state.jobs.map(j=>j.city).filter(c=>c!=='Multiple cities'),...portals.map(p=>p.city)])].sort((a,b)=>a==='All locations'?-1:a.localeCompare(b)).map(v=>`<option ${filter.city===v?'selected':''}>${e(v)}</option>`).join('')}</select><select id="sort-filter" aria-label="Sort jobs">${[['recommended','Recommended'],['deadline','Closing date'],['coverage','Keyword coverage']].map(([v,t])=>`<option value="${v}" ${filter.sort===v?'selected':''}>${t}</option>`).join('')}</select></div><div id="job-results">${jobResults()}</div></section><div class="footer-note"><span>${icon('lock')} Resume processing stays in your browser. <a href="#privacy" data-action="help">Your privacy</a></span><span>Independent workspace · Not affiliated with any employer</span></div>`}
function filtered(){let jobs=state.jobs.filter(j=>(!filter.q||`${j.title} ${j.employer} ${j.location} ${j.description}`.toLowerCase().includes(filter.q.toLowerCase()))&&(filter.sector==='All employers'||j.sector===filter.sector)&&(filter.city==='All locations'||j.city===filter.city||j.location.toLowerCase().includes(filter.city.toLowerCase()))&&(filter.tab!=='saved'||j.bookmarked)&&(filter.tab!=='closing'||(days(j)!==null&&days(j)>=0&&days(j)<=7)));if(filter.sort==='deadline')jobs.sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));if(filter.sort==='coverage'&&state.resume)jobs.sort((a,b)=>analyze(state.resume,b.keywords).score-analyze(state.resume,a.keywords).score);return jobs}
function jobResults(){const jobs=filtered();return `<div class="results-line"><label class="inline-check"><input type="checkbox" id="select-all" ${jobs.length&&jobs.every(j=>selected.has(j.id))?'checked':''}>${jobs.length} opportunit${jobs.length===1?'y':'ies'}</label><span>Curated · Verified Oct 27, 2026 · <a href="#portals" data-action="view" data-view="portals">Check latest postings</a></span></div><div class="job-grid">${jobs.length?jobs.map(jobCard).join(''):`<div class="empty-state">${icon('search')}<h3>No opportunities in this view</h3><p>Try a different location or keyword. You can add a posting from any official municipal or Ontario careers portal.</p>${btn('reset-filters','Reset filters','settings')}</div>`}</div>`}
function jobCard(j){const match=state.resume?analyze(state.resume,j.keywords):null;const d=days(j);return `<article class="job-card ${selected.has(j.id)?'selected':''}"><div class="card-top"><div class="employer-icon ${j.sector.toLowerCase()}">${j.sector==='Provincial'?icon('leaf'):e(j.city.slice(0,2).toUpperCase())}</div><div><div class="employer-name">${e(j.employer)}</div><div class="sector-label">${e(j.sector)} government${j.employer.includes('Library')?' · Library':''}</div></div><span class="spacer"></span><button class="bookmark ${j.bookmarked?'saved':''}" data-action="bookmark" data-id="${e(j.id)}" aria-label="${j.bookmarked?'Remove bookmark':'Bookmark job'}" aria-pressed="${j.bookmarked}">${icon('bookmark')}</button><input type="checkbox" class="job-select" data-id="${e(j.id)}" aria-label="Select ${e(j.title)}" ${selected.has(j.id)?'checked':''}></div><button class="card-title" data-action="detail" data-id="${e(j.id)}">${e(j.title)}</button><div class="job-meta"><span>${icon('pin')}${e(j.city==='Multiple cities'?'Multiple Ontario locations':j.location.split(' · ')[0])}</span><span>${icon('money')}${e(j.salary||'See official posting')}</span></div><div class="chips"><span class="chip filled">${e(j.type.split(' · ')[0]||'View posting')}</span>${j.keywords.slice(0,2).map(k=>`<span class="chip">${e(k)}</span>`).join('')}</div><div class="card-bottom"><span class="deadline ${d!==null&&d<=3?'urgent':''}">${icon('clock')}${deadline(j)}</span>${btn('detail','View opportunity','arrow','outline',`data-id="${e(j.id)}"`)}</div><div class="card-progress"><i style="width:${match?match.score:0}%"></i></div><div class="match-mini ${match?'':'empty'}" style="margin-top:8px">${icon(match?'check':'file')}${match?`${match.score}% keyword coverage · ${match.matched.length}/${match.total} terms`:'Add resume to see your keyword coverage'}</div></article>`}
function studio(){return `${intro('Tell your story','Your experience, well presented.','One master resume. A thoughtful draft for every role.') }<div class="studio-layout"><section class="panel"><h3>Your master resume</h3><p>Keep your original experience here. Each tailored draft is saved separately.</p><form id="resume-form"><div class="form-row"><div class="field"><label for="profile-name">Full name</label><input id="profile-name" name="name" maxlength="150" value="${e(state.profile.name)}" autocomplete="name" placeholder="Your name"></div><div class="field"><label for="profile-email">Email</label><input id="profile-email" type="email" name="email" maxlength="250" value="${e(state.profile.email)}" autocomplete="email" placeholder="you@example.com"></div></div><div class="form-row"><div class="field"><label for="profile-city">Home city</label><input id="profile-city" name="city" maxlength="100" value="${e(state.profile.city)}" placeholder="e.g. London, Ontario"></div><div class="field"><label for="profile-roles">Target roles</label><input id="profile-roles" name="roles" maxlength="300" value="${e(state.profile.roles)}"></div></div><div class="upload-box">${icon('upload')}<h4 style="margin-top:7px;font-size:12px">Bring your experience with you</h4><p>PDF, Word (.docx) or text · up to 5 MB</p><label class="btn outline" for="resume-file">Choose a file</label><input id="resume-file" type="file" accept=".pdf,.docx,.txt,text/plain,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" hidden><div id="file-status" role="status" class="small muted"></div></div><div class="field"><label for="resume-text">Resume text</label><textarea class="resume-input" id="resume-text" name="resume" maxlength="100000" placeholder="Paste your resume here, or choose a file above. Include your work experience, education, skills and achievements.">${e(state.resume)}</textarea><small>Check imported formatting. Scanned PDFs may need text pasted manually.</small></div><label class="privacy-row"><input type="checkbox" id="remember-resume" name="remember" ${state.remember?'checked':''}><span>Remember my resume and draft text on this device. Leave off on a shared computer.</span></label><div class="actions" style="margin-top:20px"><button class="btn primary" type="submit">${icon('check')}Save master resume</button>${btn('view','Back to opportunities','arrow','text','data-view="board"')}</div></form></section><aside><div class="panel"><div class="eyebrow" style="color:#8c9b7a;margin-bottom:10px">Built around your experience</div><h3>A stronger application,<br>one honest step at a time.</h3><div class="steps"><div class="step"><span class="step-no">1</span><div><h4>Add your experience</h4><p>Your master resume is the source of truth for every draft.</p></div></div><div class="step"><span class="step-no">2</span><div><h4>See the connection</h4><p>Compare a job’s editable keywords with evidence in your resume.</p></div></div><div class="step"><span class="step-no">3</span><div><h4>Tailor, review, apply</h4><p>Prepare a focused qualifications section, edit your draft, and download a Word document for the official portal.</p></div></div></div><div class="callout">Your target: <strong>more than 90% coverage</strong>. We show actual coverage and gaps. The score is a text comparison, not an employer ATS score or a prediction of hiring.</div><p class="small muted">Tailoring uses local text rules and supporting examples from your resume. It never adds a skill without evidence. Review every draft for accuracy and remove duplicated material before submitting.</p></div><div class="panel" style="margin-top:20px"><h3>Keep a copy of your journey</h3><p>Your workspace lives in this browser. Export a backup to move it to another device.</p><div class="actions">${btn('backup','Export backup','download')}${btn('restore','Restore backup','upload')}</div></div></aside></div>`}
function applications(){const entries=Object.entries(state.applications).filter(([id])=>jobById(id));return `${intro('Small steps. Real progress.','Every application, in view.','Prepare drafts here. Submit on the employer’s official portal.',entries.length?btn('export-all','Download all packages','download'):'')}${stats()}<div class="callout">Preparing a draft or opening a portal does not submit an application. Record the confirmation from the official employer portal to mark it submitted.</div>${entries.length?entries.map(([id,a])=>{const j=jobById(id);return `<article class="application-card"><div><span class="status-pill ${['Submitted','Interview'].includes(a.status)?'submitted':''}">${e(a.status)}</span><span class="small muted">${e(j.employer)}</span><h3 style="margin-top:10px">${e(j.title)}</h3><p>${e(j.city)} · ${deadline(j)}${a.confirmation?` · Confirmation: ${e(a.confirmation)}`:''}</p></div><div class="actions">${btn('review-draft','Open draft','file','outline',`data-id="${e(id)}"`)}<select class="app-status" data-id="${e(id)}" aria-label="Status for ${e(j.title)}">${['Draft','Ready','Submitted','Interview','Closed'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select>${btn('track','Track details','settings','text',`data-id="${e(id)}"`)}</div></article>`}).join(''):`<div class="empty-state">${icon('briefcase')}<h3>Your next step starts with a role.</h3><p>Choose an opportunity and prepare a tailored draft, or select several to prepare them together.</p>${btn('view','Explore opportunities','arrow','primary','data-view="board"')}</div>`}`}
function portalView(){return `${intro('Public service. Many possibilities.','Find your place in Ontario.','Official provincial and municipal career portals, Toronto to Windsor.',btn('add-job','Add a posting','plus'))}<div class="callout">Open a career portal, find a customer service or records role, then use <strong>Add a job</strong> to bring the posting and its requirements into your workspace. Listings here are curated snapshots; new jobs are not imported automatically.</div><div class="portal-grid">${portals.map(p=>`<a class="portal-card" href="${e(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer"><div class="employer-icon">${p.sector==='Provincial'?icon('leaf'):e(p.city.slice(0,2).toUpperCase())}</div><h3>${e(p.name)}</h3><p>${e(p.city)} · ${e(p.sector)}</p><span>Explore open roles ${icon('external')}</span></a>`).join('')}</div><div class="panel" style="margin-top:22px"><h3>Useful search terms</h3><p>Customer service representative · records clerk · revenue clerk · administrative clerk · service counter · registration services · records management</p>${official('https://www.gojobs.gov.on.ca/JobsAlert.aspx','Set up official OPS job alerts')}</div>`}
function openModal(html){const d=$('#modal');d.innerHTML=html;if(!d.open)d.showModal();}
function closeModal(){saveDetailEdits();$('#modal').close();detailId=null;}
function modalHead(title,sub=''){return `<div class="modal-head"><div><h2>${e(title)}</h2>${sub?`<p>${e(sub)}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`}
function openDetail(id,tab='overview',skipSave=false){if(!skipSave)saveDetailEdits();detailId=id;detailTab=tab;const j=jobById(id);if(!j)return;const app=state.applications[id];openModal(`${modalHead(j.title,j.employer+' · '+j.id)}<div class="tabs detail-tabs">${[['overview','Opportunity'],['match','Keyword match'],['draft','Application draft']].map(([v,l])=>`<button data-action="detail-tab" data-value="${v}" class="${tab===v?'active':''}">${l}</button>`).join('')}</div><div class="modal-body">${tab==='overview'?overview(j):tab==='match'?matchView(j):draftView(j,app)}</div><div class="modal-foot"><span class="small muted">${tab==='draft'?'Review your document before submitting.':'Verified '+j.verified+' · Check the official posting for updates.'}</span><div class="actions">${tab==='draft'?btn('download','Download Word','download','primary',`data-id="${e(id)}" ${app?.text?'':'disabled'}`):btn('prepare','Prepare tailored draft','spark','primary',`data-id="${e(id)}"`)}${official(j.applyUrl,'Official application')}</div></div>`)}
function overview(j){return `<div class="detail-grid"><div><h3 class="detail-heading">A role worth exploring</h3><p class="description">${e(j.description)}</p><p class="small muted" style="margin:15px 0">This is a concise summary. Read the full official ad for education, experience, eligibility, screening and application requirements.</p>${official(j.sourceUrl,'Read full official posting')}<h3 class="detail-heading" style="margin-top:24px">Key themes</h3><div class="keyword-list">${j.keywords.map(k=>`<span class="keyword">${e(k)}</span>`).join('')}</div></div><aside><div class="summary-info"><dl><dt>Location</dt><dd>${e(j.location)}</dd><dt>Compensation</dt><dd>${e(j.salary||'See official posting')}</dd><dt>Employment</dt><dd>${e(j.type||'See official posting')}</dd><dt>Closing date</dt><dd>${e(j.deadlineLabel||'See official posting')}<br>Eastern time; verify on the employer’s portal.</dd></dl></div>${days(j)!==null&&days(j)<0?'<div class="callout warm">The listed closing date has passed. Check the official portal before preparing an application.</div>':''}<div class="callout">${j.sector==='Provincial'?'OPS normally asks for a cover letter and resume in one document, up to five pages and under 1 MB, unless the posting says otherwise.':'Municipal employers use separate portals and application rules. Check the posting’s file and document requirements.'}</div>${btn('detail-tab','See resume match','spark','outline','data-value="match"')}</aside></div>`}
function scoreHtml(result,keywords){return `<div class="score-box"><div class="score-ring" style="--score:${result.score}%"><strong>${result.score}%</strong></div><div><h3>Keyword coverage</h3><p>${result.matched.length} of ${result.total} terms appear in supporting text.<br>Goal: more than 90%. ${result.score>90?'Target reached.':'Gaps remain visible.'}</p></div></div><div class="callout">A transparent text comparison: matched terms ÷ selected terms. Case, punctuation and common plural forms are normalized. This is not an ATS score, eligibility check or hiring probability.</div>`}
function matchView(j){if(!state.resume)return `<div class="empty-state">${icon('file')}<h3>Start with your experience.</h3><p>Add your master resume to see coverage, supporting examples and gaps for this role.</p>${btn('go-resume','Add master resume','upload','primary')}</div>`;const result=analyze(state.resume,j.keywords);return `${scoreHtml(result,j.keywords)}<h3 class="detail-heading">Already in your resume</h3><div class="keyword-list">${result.matched.length?result.matched.map(k=>`<span class="keyword">${icon('check')}${e(k)}</span>`).join(''):'<span class="small muted">No selected terms found yet.</span>'}</div><h3 class="detail-heading">Not yet expressed with these terms</h3><div class="keyword-list">${result.missing.map(k=>`<span class="keyword missing">${e(k)}${result.supported.includes(k)?' · equivalent evidence found':''}</span>`).join('')||'<span class="small muted">All selected terms found.</span>'}</div><h3 class="detail-heading">Evidence in your master resume</h3>${result.supported.map(k=>`<div class="evidence-row"><strong>${e(k)}</strong>${e(result.evidence[k])}</div>`).join('')||'<p class="small muted">Add concrete examples of your relevant work. Only include experience you have.</p>'}<div class="separator"></div><form id="keywords-form"><div class="field"><label for="keywords-edit">Review the terms used for this role</label><textarea id="keywords-edit" style="min-height:80px">${e(j.keywords.join(', '))}</textarea><small>Comma-separated terms, up to 40. Include mandatory qualifications as well as skills. Changing this list changes the coverage score.</small></div><button class="btn outline" type="submit">${icon('check')}Save keyword list</button></form>`}
function draftView(j,a){if(!a)return `<div class="empty-state">${icon('spark')}<h3>A personal draft for this opportunity.</h3><p>We’ll bring relevant experience to the top and keep your original history. Skills without evidence stay as gaps.</p>${btn('prepare','Create tailored draft','spark','primary',`data-id="${e(j.id)}"`)}</div>`;if(!a.text)return `<div class="callout">Your draft text was not remembered on this device. Add your resume and regenerate the draft, or paste a saved version below.</div><textarea class="draft-area" id="draft-text" aria-label="Tailored resume" placeholder="Paste a saved draft here…"></textarea><div class="actions">${btn('recalculate','Save pasted draft','check','outline')}${btn('prepare','Regenerate from master resume','spark','primary',`data-id="${e(j.id)}"`)}</div>`;const score=analyze(scoringText(a.text),j.keywords);return `<div id="draft-score">${scoreHtml(score,j.keywords)}</div><div class="callout warm">This draft adds an evidence-based qualifications section and preserves your original resume. Review it, remove duplication, and confirm every statement. ${j.sector==='Provincial'?'Keep the combined OPS cover letter and resume within five pages unless the ad says otherwise.':''}</div><div class="field"><label for="draft-text">Tailored resume · editable</label><textarea id="draft-text" class="draft-area" maxlength="100000">${e(a.text)}</textarea></div><div class="field"><label for="cover-text">Cover letter · optional, included before the resume</label><textarea id="cover-text" maxlength="30000" placeholder="Write your cover letter here. Use concrete examples from your experience and address the requirements in the posting.">${e(a.cover||'')}</textarea><small>A combined Word document is created when a cover letter is included.</small></div><div class="actions">${btn('recalculate','Update coverage','spark')}${btn('generate-cover','Create cover letter draft','file')}${btn('copy-draft','Copy resume','file','text')}</div><div class="separator"></div><div class="checks"><label><input type="checkbox" id="reviewed-check" ${a.reviewed?'checked':''}>I reviewed this document and it accurately represents my experience.</label><label><input type="checkbox" id="confirmed-check" ${a.confirmed?'checked':''}>I checked the official posting’s eligibility, screening questions and document requirements.</label></div><div class="actions">${btn('mark-ready','Mark ready to apply','check','primary',`data-id="${e(j.id)}"`)}${btn('track','Add tracking details','settings','outline',`data-id="${e(j.id)}"`)}</div>${a.changes?.length?`<p class="small muted" style="margin-top:20px">${a.changes.map(e).join('<br>')}</p>`:''}`}
function scoringText(text){return String(text).split('\n').filter(line=>!line.startsWith('Tailored application:')).join('\n')}
function saveDetailEdits(){if(!detailId||detailTab!=='draft'||!$('#draft-text'))return;let a=state.applications[detailId];if(!a)return;a.text=$('#draft-text').value;a.cover=$('#cover-text')?$('#cover-text').value:(a.cover||'');a.reviewed=!!$('#reviewed-check')?.checked;a.confirmed=!!$('#confirmed-check')?.checked;a.updated=new Date().toISOString();if(a.status==='Ready'&&(!a.reviewed||!a.confirmed))a.status='Draft';persist()}
function prepare(id,quiet=false){saveDetailEdits();if(!state.resume.trim()){if(!quiet){closeModal();state.view='resume';render();toast('Add your master resume first, then prepare a draft.')}return false}const j=jobById(id);if(!j)return false;if(state.applications[id]?.text){if(!quiet)openDetail(id,'draft');return true}const result=createDraft(state.resume,j,j.keywords,state.profile);state.applications[id]={...(state.applications[id]||{}),text:result.text,cover:'',status:'Draft',reviewed:false,confirmed:false,changes:result.changes,updated:new Date().toISOString(),notes:state.applications[id]?.notes||'',confirmation:state.applications[id]?.confirmation||''};persist();if(!quiet){render();openDetail(id,'draft')}return true}
function download(name,data,mime){const blob=new Blob([data],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function fileName(j){return `${(state.profile.name||'Applicant').replace(/[^a-z0-9 -]/gi,'').trim().replace(/\s+/g,'_')}_${j.id.replace(/[^a-z0-9-]/gi,'')}`}
function packageText(a){return (a.cover?a.cover.trim()+'\n\n--- PAGE BREAK ---\n\n':'')+a.text}
function downloadDoc(id){saveDetailEdits();const j=jobById(id),a=state.applications[id];if(!a?.text){toast('Create or paste a draft before downloading.');return}const data=createDocx(packageText(a));if(j.sector==='Provincial'&&data.byteLength>=1000000){toast('This document exceeds the OPS 1 MB limit. Shorten it before uploading.');return}download(fileName(j)+'.docx',data,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');toast('Word document downloaded. Check formatting and page count before applying.')}
function exportPackages(ids){saveDetailEdits();const files=[];for(const id of ids){const a=state.applications[id],j=jobById(id);if(!a?.text||!j)continue;files.push({name:fileName(j)+'.docx',data:createDocx(packageText(a))});files.push({name:fileName(j)+'_checklist.txt',data:`${j.title}\n${j.employer}\n${j.id}\n\nOfficial posting: ${j.sourceUrl}\nApply: ${j.applyUrl}\nDeadline: ${j.deadlineLabel}\n\nKeyword coverage: ${analyze(scoringText(a.text),j.keywords).score}% (local text comparison, not an employer ATS score).\n\nBefore applying:\n- Read the full posting and check eligibility, education and experience requirements.\n- Review all resume and cover letter statements.\n- Verify document formatting, page count, and upload size limits.\n- Answer employer-specific screening questions.\n- Submit on the official portal.\n- Save the confirmation in CivicPath.\n\nThis package has NOT been submitted.\n`})}if(!files.length){toast('Create a draft first. Drafts not remembered on this device need to be regenerated.');return}files.push({name:'START_HERE.txt',data:'CivicPath application packages\n\nThese are editable drafts, not submitted applications. Review each document and submit separately on its official employer portal.\nOPS normally requires one cover letter and resume document, no more than five pages and under 1 MB; follow each posting if it differs. Municipal rules vary.\nNever add qualifications or experience you do not have.\n'});download('CivicPath_application_packages.zip',createZip(files),'application/zip');toast(`Downloaded ${Math.floor((files.length-1)/2)} application package(s).`)}
function addJob(){detailId=null;openModal(`${modalHead('Bring an opportunity into your workspace','Copy the details from an official employer posting.')}<form id="add-job-form"><div class="modal-body"><div class="form-row"><div class="field"><label for="job-title">Job title *</label><input id="job-title" name="title" required maxlength="250" placeholder="e.g. Records Clerk"></div><div class="field"><label for="job-employer">Employer *</label><input id="job-employer" name="employer" required maxlength="250" placeholder="e.g. City of Windsor"></div></div><div class="form-row"><div class="field"><label for="job-city">City *</label><input id="job-city" name="city" required maxlength="100" placeholder="e.g. Windsor"></div><div class="field"><label for="job-sector">Employer type</label><select id="job-sector" name="sector"><option>Municipal</option><option>Provincial</option></select></div></div><div class="field"><label for="job-url">Official posting URL *</label><input id="job-url" name="url" type="url" required placeholder="https://…"><small>Use the employer’s official careers website.</small></div><div class="form-row"><div class="field"><label for="job-deadline">Closing date</label><input id="job-deadline" name="deadline" type="date"></div><div class="field"><label for="job-salary">Pay and employment type</label><input id="job-salary" name="salary" maxlength="250" placeholder="e.g. $30/hour · permanent full-time"></div></div><div class="field"><label for="job-description">Full job description and qualifications *</label><textarea id="job-description" name="description" required minlength="60" maxlength="15000" placeholder="Paste the responsibilities, required qualifications, education, experience and application instructions…"></textarea></div><div class="field"><label for="job-keywords">Important skills and qualifications</label><input id="job-keywords" name="keywords" maxlength="2000" placeholder="Optional: records management, customer service, Excel…"><small>Leave blank to extract a starter list from the posting. Review it before using the score.</small></div></div><div class="modal-foot"><span class="small muted">Your saved posting is stored in this browser.</span><button class="btn primary" type="submit">${icon('plus')}Add opportunity</button></div></form>`)}
function track(id){saveDetailEdits();detailId=null;const j=jobById(id),a=state.applications[id];if(!j||!a)return;openModal(`${modalHead('Keep the next step in view',j.title)}<form id="track-form" data-id="${e(id)}"><div class="modal-body"><div class="field"><label for="track-status">Application status</label><select id="track-status" name="status">${['Draft','Ready','Submitted','Interview','Closed'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="confirmation">Official confirmation number or acknowledgement</label><input id="confirmation" name="confirmation" value="${e(a.confirmation||'')}" maxlength="500" placeholder="e.g. submission confirmation number or email acknowledgement"><small>Required for Submitted or Interview. Opening a portal does not submit an application.</small></div><div class="field"><label for="track-notes">Notes and next steps</label><textarea id="track-notes" name="notes" maxlength="10000">${e(a.notes||'')}</textarea></div><div class="callout">Marking Ready requires both document review and eligibility checks in the application draft.</div></div><div class="modal-foot">${btn('remove-app','Remove from tracker','trash','text',`data-id="${e(id)}"`)}<button class="btn primary" type="submit">${icon('check')}Save tracking details</button></div></form>`)}
function help(){saveDetailEdits();detailId=null;openModal(`${modalHead('A workspace for your next chapter','How CivicPath works and where your information lives.')}<div class="modal-body"><h3 class="detail-heading">Prepare together. Submit individually.</h3><p class="description">Select several opportunities to create separate resume drafts in one click. Download them together as a ZIP. Each government employer still requires its own application, screening answers and confirmation. CivicPath does not submit applications or access employer accounts.</p><div class="separator"></div><h3 class="detail-heading">An honest coverage score</h3><p class="description">The percentage shows how many selected keywords appear in supporting resume text. Your goal is more than 90%, when your experience supports it. The list is editable and not exhaustive. This is not an employer ATS score or a measure of eligibility. Mandatory education, licences and experience need separate review. Drafts use local rules to bring supported qualifications forward; they do not use a connected AI service.</p><div class="separator"></div><h3 class="detail-heading">Your resume stays in this browser</h3><p class="description">File reading and tailoring run locally in the page. Resume and draft text stay in memory unless you choose “Remember my resume and draft text on this device.” Job metadata, profile and tracking details are saved in this browser’s local storage. Backup files include your resume and drafts. Use your own device and keep backup files private. Local data is not synchronized between devices or recovered by this site. Hosting access does not grant access to your browser’s local data.</p><div class="actions" style="margin-top:20px">${btn('backup','Export workspace backup','download')}${btn('restore','Restore backup','upload')}${btn('clear-data','Clear saved workspace','trash','danger')}</div><div class="separator"></div><p class="small muted">Curated listings were verified on October 27, 2026. Use the official portal to confirm availability and requirements. CivicPath is independent of the Ontario government and municipalities.</p></div>`)}
function setStatus(id,status,confirmation){const a=state.applications[id];if(!a)return false;if(['Submitted','Interview'].includes(status)&&!(confirmation||a.confirmation)?.trim()){toast('Add the official submission acknowledgement in tracking details first.');track(id);return false}if(status==='Ready'&&/\[(?:Add|Explain|Your name)[^\]]*\]/i.test(a.cover||'')){toast('Complete the bracketed sections in your cover letter before marking Ready.');openDetail(id,'draft');return false}if(status==='Ready'&&(!a.reviewed||!a.confirmed)){toast('Review your draft and complete both checks before marking it Ready.');openDetail(id,'draft');return false}a.status=status;if(['Submitted','Interview'].includes(status))a.submitted=a.submitted||new Date().toISOString();persist();return true}
const actions={
 view(el){saveDetailEdits();if($('#modal').open)closeModal();state.view=el.dataset.view;render();window.scrollTo(0,0)},menu(){ $('#sidebar').classList.toggle('open')},help,close:closeModal,'add-job':addJob,
 detail(el){openDetail(el.dataset.id)},'review-draft'(el){openDetail(el.dataset.id,'draft')},'detail-tab'(el){openDetail(detailId,el.dataset.value)},
 bookmark(el){const j=jobById(el.dataset.id);j.bookmarked=!j.bookmarked;persist();render()},
 'filter-tab'(el){filter.tab=el.dataset.value;render()},'reset-filters'(){filter={q:'',sector:'All employers',city:'All locations',tab:'all',sort:'recommended'};render()},
 'clear-selection'(){selected.clear();render()},'go-resume'(){closeModal();state.view='resume';render()},prepare(el){prepare(el.dataset.id)},
 'prepare-selected'(){if(!state.resume.trim()){state.view='resume';render();toast('Add your master resume, then prepare the selected opportunities.');return}let count=0;for(const id of selected)if(prepare(id,true))count++;selected.clear();state.view='applications';render();toast(`${count} draft(s) ready for review. Download packages from this page.`)},
 download(el){downloadDoc(el.dataset.id)},'export-all'(){exportPackages(Object.keys(state.applications))},'recalculate'(){saveDetailEdits();openDetail(detailId,'draft');toast('Keyword coverage updated from your edited draft.')},
 'generate-cover'(){saveDetailEdits();const a=state.applications[detailId],j=jobById(detailId);if(a.cover?.trim()){toast('Your existing cover letter is kept. Edit it directly to make changes.');return}const match=analyze(state.resume,j.keywords);const examples=[...new Set(match.supported.slice(0,3).map(k=>match.evidence[k]))];a.cover=`${[state.profile.name,state.profile.email,state.profile.city].filter(Boolean).join('\n')}\n\nRe: ${j.title} (${j.id})\n\nDear Hiring Committee,\n\nI am applying for the ${j.title} position with ${j.employer}. My relevant experience includes:\n\n${examples.length?examples.map(v=>'• '+v.replace(/^[•*\-]\s*/, '')).join('\n'):'[Add a specific example of relevant work experience.]'}\n\n[Explain how these examples meet the posting’s required qualifications. Add your genuine reason for seeking this role.]\n\nThank you for considering my application. I would welcome the opportunity to discuss my experience.\n\nSincerely,\n${state.profile.name||'[Your name]'}`;a.reviewed=false;if(a.status==='Ready')a.status='Draft';persist();openDetail(detailId,'draft',true);toast('Cover letter starter added. Complete the bracketed sections before submitting.')},
 async 'copy-draft'(){saveDetailEdits();try{await navigator.clipboard.writeText(state.applications[detailId].text);toast('Resume copied.')}catch{toast('Clipboard unavailable. Select the resume text and copy it manually.')}},
 'mark-ready'(el){saveDetailEdits();if(setStatus(el.dataset.id,'Ready')){render();openDetail(el.dataset.id,'draft');toast('Marked Ready. Submit on the official employer portal.')}},track(el){track(el.dataset.id)},
 'remove-app'(el){const id=el.dataset.id;openModal(`${modalHead('Remove this application from your tracker?')}<div class="modal-body"><p class="description">The prepared draft and notes for this role will be removed. Your master resume and saved posting will remain.</p></div><div class="modal-foot">${btn('close','Cancel','close')}${btn('confirm-remove','Remove draft','trash','danger',`data-id="${e(id)}"`)}</div>`);detailId=null},'confirm-remove'(el){delete state.applications[el.dataset.id];persist();closeModal();render();toast('Draft removed from your tracker.')},
 backup(){saveDetailEdits();detailId=null;openModal(`${modalHead('Export your workspace backup')}<div class="modal-body"><p class="description">This file contains your profile, saved jobs, tracking notes, master resume and draft text currently in this workspace. Keep it private. You can restore it in this browser or on another device.</p></div><div class="modal-foot">${btn('close','Cancel','close')}${btn('confirm-backup','Download private backup','download','primary')}</div>`)},'confirm-backup'(){download('CivicPath_private_backup.json',JSON.stringify({version:1,jobs:state.jobs,profile:state.profile,resume:state.resume,remember:true,applications:state.applications},null,2),'application/json');closeModal();toast('Private backup downloaded. Keep it somewhere safe.')},restore(){saveDetailEdits();$('#restore-file').click()},
 'clear-data'(){detailId=null;openModal(`${modalHead('Clear this browser’s workspace?')}<div class="modal-body"><p class="description">This removes your resume, drafts, profile, tracking details and added jobs from this browser. Download a backup first if you want to keep them.</p></div><div class="modal-foot">${btn('close','Keep my workspace','close')}${btn('confirm-clear','Clear workspace','trash','danger')}</div>`)},'confirm-clear'(){localStorage.removeItem(KEY);state={view:'board',jobs:initialJobs.map(j=>({...j,bookmarked:false})),profile:{name:'',email:'',city:'',roles:'Customer service, records clerk'},resume:'',remember:false,applications:{}};selected.clear();closeModal();render();toast('Saved data cleared. Curated opportunities restored.')}
};
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const fn=actions[el.dataset.action];if(fn){ev.preventDefault();Promise.resolve(fn(el)).catch(err=>{console.error(err);toast('That action could not finish. Please try again.')})}});
document.addEventListener('input',ev=>{if(ev.target.id==='job-search'){filter.q=ev.target.value;$('#job-results').innerHTML=jobResults()}if(ev.target.id==='draft-text'||ev.target.id==='cover-text'){const a=state.applications[detailId];if(a){a.reviewed=false;if(a.status==='Ready')a.status='Draft';const c=$('#reviewed-check');if(c)c.checked=false}}});
document.addEventListener('change',async ev=>{const el=ev.target;if(['sector-filter','city-filter','sort-filter'].includes(el.id)){filter[{'sector-filter':'sector','city-filter':'city','sort-filter':'sort'}[el.id]]=el.value;$('#job-results').innerHTML=jobResults()}if(el.classList.contains('job-select')){el.checked?selected.add(el.dataset.id):selected.delete(el.dataset.id);render()}if(el.id==='select-all'){for(const j of filtered())el.checked?selected.add(j.id):selected.delete(j.id);render()}if(el.classList.contains('app-status')){if(setStatus(el.dataset.id,el.value))render();else el.value=state.applications[el.dataset.id].status}if(el.id==='resume-file'){await importResume(el.files[0])}if(el.id==='restore-file'&&el.files[0]){const f=el.files[0];el.value='';if(f.size>10000000){toast('Backup is too large. Use a CivicPath backup under 10 MB.');return}try{const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.jobs)||data.jobs.some(j=>!j.id||!j.title))throw Error('Invalid backup');const restored=validSaved(data);storeRestore(restored)}catch{toast('This file is not a valid CivicPath backup. Your workspace was kept.')}}});
let pendingRestore=null;
function storeRestore(restored){pendingRestore=restored;detailId=null;openModal(`${modalHead('Restore this workspace backup?')}<div class="modal-body"><p class="description">Replace the current workspace with ${restored.jobs.length} saved opportunities and ${Object.keys(restored.applications).length} tracked applications from this backup. Resume and drafts will be remembered on this device. Export your current workspace first if you want to keep it.</p></div><div class="modal-foot">${btn('close','Cancel','close')}${btn('confirm-restore','Replace workspace','upload','primary')}</div>`)}
actions['confirm-restore']=()=>{if(!pendingRestore)return;state={...state,...pendingRestore,view:'board'};pendingRestore=null;selected.clear();persist();closeModal();render();toast('Backup restored on this device.')};
document.addEventListener('submit',ev=>{const form=ev.target;if(form.id==='resume-form'){ev.preventDefault();const fd=new FormData(form);state.profile={name:String(fd.get('name')).trim(),email:String(fd.get('email')).trim(),city:String(fd.get('city')).trim(),roles:String(fd.get('roles')).trim()};state.resume=String(fd.get('resume')).trim();state.remember=!!fd.get('remember');persist();render();toast(state.resume?'Master resume saved. Your job matches are ready to explore.':'Profile saved. Add resume text to prepare drafts.')}if(form.id==='keywords-form'){ev.preventDefault();const j=jobById(detailId);const terms=$('#keywords-edit').value.split(',').map(s=>s.trim()).filter(Boolean);if(!terms.length){toast('Include at least one keyword or qualification.');return}j.keywords=[...new Set(terms)].slice(0,40);persist();render();openDetail(j.id,'match');toast('Keyword list updated.')}if(form.id==='add-job-form'){ev.preventDefault();const fd=new FormData(form),url=safeUrl(fd.get('url'));if(!url){toast('Enter a secure https:// URL for the official posting.');return}const description=String(fd.get('description')).trim(),keywords=String(fd.get('keywords')).trim();let j=sanitizeJob({id:`JOB-${crypto.randomUUID().slice(0,8)}`,title:fd.get('title'),employer:fd.get('employer'),city:fd.get('city'),location:fd.get('city'),sector:fd.get('sector'),sourceUrl:url,applyUrl:url,deadline:fd.get('deadline'),deadlineLabel:fd.get('deadline')?`${fd.get('deadline')} · confirm exact time on posting`:'See official posting',salary:fd.get('salary'),type:'See official posting',description,keywords:keywords?keywords.split(',').map(v=>v.trim()).filter(Boolean):extractKeywords(description),verified:today()});if(!j.keywords.length){toast('Add important qualifications in the keyword field.');return}state.jobs.unshift(j);persist();closeModal();state.view='board';filter={q:'',sector:'All employers',city:'All locations',tab:'all',sort:'recommended'};render();toast('Opportunity added. Review its keyword list against the full posting.')}if(form.id==='track-form'){ev.preventDefault();const fd=new FormData(form),id=form.dataset.id,a=state.applications[id],status=String(fd.get('status')),conf=String(fd.get('confirmation')).trim();if(['Submitted','Interview'].includes(status)&&!conf){toast('Add the employer’s submission confirmation or acknowledgement.');return}if(status==='Ready'&&/\[(?:Add|Explain|Your name)[^\]]*\]/i.test(a.cover||'')){toast('Complete the bracketed sections in your cover letter before marking Ready.');openDetail(id,'draft');return false}if(status==='Ready'&&(!a.reviewed||!a.confirmed)){toast('Complete both review checks in the application draft first.');return}a.confirmation=conf;a.notes=String(fd.get('notes'));if(setStatus(id,status,conf)){closeModal();render();toast('Application tracking updated.')}}});
$('#modal').addEventListener('cancel',ev=>{ev.preventDefault();closeModal()});$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const rect=ev.target.getBoundingClientRect();if(ev.clientX<rect.left||ev.clientX>rect.right||ev.clientY<rect.top||ev.clientY>rect.bottom)closeModal()}});
async function importResume(file){if(!file)return;const status=$('#file-status');if(file.size>5*1024*1024){toast('Choose a resume smaller than 5 MB.');return}status.textContent='Reading your file locally…';try{let text='';if(/\.txt$/i.test(file.name))text=await file.text();else if(/\.docx$/i.test(file.name)){const mammoth=await import('./vendor/mammoth.js');text=(await mammoth.default.extractRawText({arrayBuffer:await file.arrayBuffer()})).value}else if(/\.pdf$/i.test(file.name)){const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;if(pdf.numPages>40)throw Error('Please use a resume with 40 pages or fewer.');const pages=[];for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),content=await page.getTextContent();pages.push(content.items.map(it=>it.str+(it.hasEOL?'\n':' ')).join(''))}text=pages.join('\n\n');await pdf.destroy()}else throw Error('Use a PDF, DOCX or TXT file. Older .doc files can be saved as DOCX or pasted as text.');if(!text.trim())throw Error('No readable text found. Paste the text from your resume instead; scanned PDFs need OCR first.');$('#resume-text').value=text.slice(0,100000);status.textContent=`${file.name} · text imported. Review below and save.`;toast('Resume text imported. Review it and save your master resume.')}catch(err){status.textContent=err.message||'Could not read this file. Paste your resume text below.';toast('File import could not finish. You can paste your resume text instead.')}}
render();
